//! Codegen реестра канонических спеков ВИДОВ из файловой раскладки (ARCHITECTURE.md
//! §5; ORCHESTRATION «два агента НЕ редактируют одни файлы»).
//!
//! # Зачем codegen, а не inventory/linkme
//! Распределённая саморегистрация через линкер-секцию (inventory) НЕ надёжна для нашего
//! графа крейтов: `core`/форматы — промежуточные `rlib`, и модуль вида, на символы
//! которого никто не ссылается, ВЫРЕЗАЕТСЯ DCE вместе с его `submit!` — вид молча
//! исчезает из реестра (проверено: registry-only вид не виден downstream-бинарю). Для
//! parallel-safe грайнда это недопустимо. Поэтому реестр строится как ОБЫЧНЫЙ ссылаемый
//! `&[...]`: каждый элемент ИМЕНУЕТ символ модуля вида (`<вид>::<вид>`), что держит
//! модуль живым → DCE не срабатывает. Robust by construction, без магии линкера.
//!
//! # Контракт
//! Файл `src/spec/metadata/<вид>.rs` ОБЯЗАН определить `pub fn <вид>() -> &'static
//! EntitySpec` (имя функции = stem файла). Добавил файл → пересборка подхватывает его в
//! `pub mod` (через `metadata/mod.rs`) и в `SPEC_CTORS` (реестр) без правки общих файлов.
//!
//! Генерируются два include-фрагмента:
//! * `metadata_mods.rs` — `pub mod <вид>;` (включается в `spec/metadata/mod.rs`);
//! * `metadata_ctors.rs` — `SPEC_CTORS` (включается в `spec/registry.rs`).

use std::path::Path;

fn main() {
    emit_since_tables();
    emit_version_registry_tables();
    emit_format_layout_tables();

    let dir = Path::new("src/spec/metadata");
    println!("cargo:rerun-if-changed={}", dir.display());

    let mut modules: Vec<String> = Vec::new();
    // Виды, чей файл ОБЪЯВЛЯЕТ `pub const PRODUCED_CATEGORIES` (платформенный блок
    // `producedTypes`/`InternalInfo`). Собираются grep'ом содержимого файла — так вид с
    // producedTypes объявляет свои категории В СВОЁМ спек-файле, а реестр (ниже)
    // подхватывает их БЕЗ правки общих файлов (parallel-safe, зеркало `SPEC_CTORS`).
    let mut produced: Vec<String> = Vec::new();
    for entry in std::fs::read_dir(dir).expect("read src/spec/metadata") {
        let path = entry.expect("dir entry").path();
        // Перегенерация и при правке самих файлов видов (не только при появлении новых).
        println!("cargo:rerun-if-changed={}", path.display());
        if path.extension().and_then(|e| e.to_str()) != Some("rs") {
            continue;
        }
        let stem = path
            .file_stem()
            .and_then(|s| s.to_str())
            .expect("utf-8 stem");
        if stem == "mod" {
            continue;
        }
        // Детект per-kind `PRODUCED_CATEGORIES` по содержимому — вид сам объявляет блок в
        // своём файле; ключ вида берётся из `<стем>().entity` (единый источник §1.6).
        let src = std::fs::read_to_string(&path).expect("read spec file");
        if src.contains("pub const PRODUCED_CATEGORIES") {
            produced.push(stem.to_string());
        }
        modules.push(stem.to_string());
    }
    modules.sort();
    produced.sort();

    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR");
    // Абсолютный путь каталога видов из `CARGO_MANIFEST_DIR` (без `canonicalize`, чтобы
    // не получить Windows `\\?\` UNC-префикс, который ломает `#[path]`). `#[path]`
    // обязателен: `pub mod` живёт в include!-фрагменте (OUT_DIR), а исходник вида — в
    // `src/spec/metadata`; без явного пути rustc искал бы `<вид>.rs` рядом с фрагментом.
    let manifest = std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR");
    let abs_str = format!("{manifest}/src/spec/metadata").replace('\\', "/");

    // (1) `#[path] pub mod <вид>;` — включается в `spec/metadata/mod.rs` (модули живут
    //     ТАМ, сохраняя путь `spec::metadata::<вид>` для всех зеркал/импортов).
    let mut mods = String::from("// @generated by build.rs — do not edit.\n");
    for m in &modules {
        mods.push_str(&format!("#[path = \"{abs_str}/{m}.rs\"]\npub mod {m};\n"));
    }
    std::fs::write(Path::new(&out_dir).join("metadata_mods.rs"), mods).expect("write mods");

    // (2) `SPEC_CTORS` — ссылаемый массив конструкторов; ИМЕНУЕТ `<вид>::<вид>`, чем
    //     держит модули живыми (DCE-safe). Включается в `spec/registry.rs`.
    let mut ctors = String::from("// @generated by build.rs — do not edit.\n");
    ctors.push_str(
        "/// Все спек-конструкторы видов (по файлам `spec/metadata`). Ссылаемый `const`\n\
         /// держит модули живыми (DCE-safe); реестр строится из него.\n\
         pub static SPEC_CTORS: &[fn() -> &'static crate::spec::common::EntitySpec] = &[\n",
    );
    for m in &modules {
        ctors.push_str(&format!("    crate::spec::metadata::{m}::{m},\n"));
    }
    ctors.push_str("];\n");

    // (3) `PRODUCED_CTORS` — ссылаемый массив `(kind-ctor, &[ProducedCategory])` ТОЛЬКО
    //     для видов, чей файл объявил `pub const PRODUCED_CATEGORIES`. Ключ вида берётся
    //     в рантайме из `(ctor)().entity` (§1.6: единый источник кода вида). Включается в
    //     `spec/registry.rs`; `produced_categories_for` строит из него `kind -> категории`.
    ctors.push_str(
        "\n/// Пары `(конструктор спека вида, его категории producedTypes)` для видов,\n\
         /// объявивших `pub const PRODUCED_CATEGORIES` (детект build.rs по содержимому\n\
         /// файла). Ключ вида = `(ctor)().entity`. Пусто у видов без платформенного блока.\n\
         #[allow(clippy::type_complexity)]\n\
         pub static PRODUCED_CTORS: &[(\n    \
             fn() -> &'static crate::spec::common::EntitySpec,\n    \
             &[crate::spec::common::ProducedCategory],\n\
         )] = &[\n",
    );
    for m in &produced {
        ctors.push_str(&format!(
            "    (crate::spec::metadata::{m}::{m}, crate::spec::metadata::{m}::PRODUCED_CATEGORIES),\n"
        ));
    }
    ctors.push_str("];\n");
    std::fs::write(Path::new(&out_dir).join("metadata_ctors.rs"), ctors).expect("write ctors");
}

/// Codegen since-таблиц из ИНВЕНТАРЯ (§1.5): `inventory/metamodel.jsonl` (поля видов) и
/// `inventory/enums.jsonl` (литералы перечислений). Оба несут `since` — версию ПЛАТФОРМЫ,
/// с которой свойство/литерал существует (источник: EDT-метамодель `MdClass.xcore` /
/// `Common.xcore`).
///
/// Эмитим версию ПЛАТФОРМЫ как есть, БЕЗ перевода в версию формата: маппинг
/// платформа→формат живёт РОВНО в одном месте — `VERSION_TABLE` (`src/version/mod.rs`,
/// зеркало FORMATS.md §2). Продублировать его здесь значило бы завести второй хардкод
/// таблицы версий; вместо этого `src/version/since.rs` разрешает платформу через ту же
/// `VERSION_TABLE` в рантайме, и тест сверяет, что КАЖДАЯ запись разрешается.
fn emit_since_tables() {
    // Инвентарь лежит в корне репозитория (крейт — `crates/core`).
    let root = repo_root();
    let metamodel = root.join("inventory/metamodel.jsonl");
    let enums = root.join("inventory/enums.jsonl");
    println!("cargo:rerun-if-changed={}", metamodel.display());
    println!("cargo:rerun-if-changed={}", enums.display());

    // (kind, field, "8.3.27") — поле вида, введённое версией платформы.
    let mut fields: Vec<(String, String, String)> = Vec::new();
    for line in read_jsonl(&metamodel) {
        let kind = line["kind"].as_str().expect("metamodel record has kind");
        for f in line["fields"].as_array().into_iter().flatten() {
            if let Some(since) = f["since"].as_str() {
                let name = f["name"].as_str().expect("field has name");
                fields.push((kind.to_string(), name.to_string(), since.to_string()));
            }
        }
    }

    // (enum, literal, "8.3.25") — литерал перечисления, введённый версией платформы.
    // Плотные таблицы (`UsedMobileApplicationFunctionalities`) эмитят ВСЕ литералы
    // перечисления, поэтому набор литералов — тоже функция версии (FORMATS.md §4).
    let mut literals: Vec<(String, String, String)> = Vec::new();
    for line in read_jsonl(&enums) {
        let name = line["name"].as_str().expect("enum record has name");
        for l in line["literals"].as_array().into_iter().flatten() {
            if let Some(since) = l["since"].as_str() {
                let lit = l["name"].as_str().expect("literal has name");
                literals.push((name.to_string(), lit.to_string(), since.to_string()));
            }
        }
    }

    fields.sort();
    literals.sort();

    let mut out = String::from(
        "// @generated by build.rs from inventory/{metamodel,enums}.jsonl — do not edit.\n\n",
    );
    out.push_str(
        "/// `(вид, поле, версия ПЛАТФОРМЫ (major, minor, patch))` — поле, введённое версией.\n\
         /// Разрешается в [`Since`](crate::version::Since) через `VERSION_TABLE` (см. `since.rs`).\n\
         pub static SINCE_FIELDS_RAW: &[(&str, &str, (u16, u16, u16))] = &[\n",
    );
    for (kind, name, since) in &fields {
        out.push_str(&format!(
            "    ({:?}, {:?}, {}),\n",
            kind,
            name,
            platform_tuple(since)
        ));
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// `(перечисление, литерал, версия ПЛАТФОРМЫ)` — литерал, введённый версией.\n\
         pub static SINCE_LITERALS_RAW: &[(&str, &str, (u16, u16, u16))] = &[\n",
    );
    for (en, lit, since) in &literals {
        out.push_str(&format!(
            "    ({:?}, {:?}, {}),\n",
            en,
            lit,
            platform_tuple(since)
        ));
    }
    out.push_str("];\n\n");

    // --- ВИТНЕССЕННЫЕ версионные факты вне метамодели (models/version_facts.jsonl) ---------
    //
    // Метамодель EDT знает `since` только для МЕТАДАННЫХ и только там, где xcore несёт маркер;
    // у форм таких данных нет вовсе. Недостающее добыто у ПЛАТФОРМЫ (`scripts/version_probe.sh`
    // → `tools/build_version_facts.py`) и живёт ДАННЫМИ; здесь оно лишь переносится в таблицу.
    //
    // Ключ — (ВЛАДЕЛЕЦ, каноническое имя): в отличие от метамодели, имя поля формы НЕ
    // однозначно (одно `orientation`/`color` бывает у разных контролов), поэтому поиск только
    // по имени тут был бы неверен. Версия здесь — уже версия ФОРМАТА (её и наблюдает дамп),
    // а не платформы: свидетель штампует себя форматом.
    let facts = root.join("models/version_facts.jsonl");
    println!("cargo:rerun-if-changed={}", facts.display());
    let mut form_since: Vec<(String, String, String)> = Vec::new();
    // (владелец, каноническое имя, версия-источник, версия-цель, значение) — факт
    // `materialized`: поднимая источник, цель САМА проставляет свойство этим значением.
    let mut form_materialized: Vec<(String, String, String, String, String)> = Vec::new();
    // (владелец, старое имя, новое имя, версия-источник, версия-цель) — факт `renamed`.
    let mut form_renamed: Vec<(String, String, String, String, String)> = Vec::new();
    if facts.exists() {
        for line in read_jsonl(&facts) {
            if line["area"].as_str() != Some("forms") {
                continue;
            }
            let owner = line["owner"].as_str().expect("fact record has owner");
            match line["fact"].as_str() {
                Some("since") => {
                    let canonical = line["canonical"]
                        .as_str()
                        .expect("since fact has canonical name");
                    let format = line["format"].as_str().expect("since fact has format");
                    form_since.push((
                        owner.to_string(),
                        canonical.to_string(),
                        format.to_string(),
                    ));
                }
                // Владелец `Properties` — не контрол, а XML-обёртка свойств ДЕСКРИПТОРА:
                // словарь этих фактов (`Properties`/`StandardAttribute`) не совпадает со
                // словарём контролов, по которому ключуется тело формы. Берём только факты о
                // КОНТРОЛАХ — там `owner` и есть вид контрола.
                Some("materialized") if owner != "Properties" => {
                    form_materialized.push((
                        owner.to_string(),
                        line["canonical"]
                            .as_str()
                            .expect("materialized fact has canonical name")
                            .to_string(),
                        line["absent_in"]
                            .as_str()
                            .expect("materialized fact has absent_in")
                            .to_string(),
                        line["format"]
                            .as_str()
                            .expect("materialized fact has format")
                            .to_string(),
                        line["value"]
                            .as_str()
                            .expect("materialized fact has value")
                            .to_string(),
                    ));
                }
                Some("renamed") if owner != "Properties" => {
                    form_renamed.push((
                        owner.to_string(),
                        line["from_canonical"]
                            .as_str()
                            .expect("renamed fact has from_canonical")
                            .to_string(),
                        line["to_canonical"]
                            .as_str()
                            .expect("renamed fact has to_canonical")
                            .to_string(),
                        line["from_format"]
                            .as_str()
                            .expect("renamed fact has from_format")
                            .to_string(),
                        line["format"]
                            .as_str()
                            .expect("renamed fact has format")
                            .to_string(),
                    ));
                }
                _ => {}
            }
        }
    }
    form_since.sort();
    form_since.dedup();
    form_materialized.sort();
    form_materialized.dedup();
    form_renamed.sort();
    form_renamed.dedup();

    out.push_str(
        "/// `(владелец, каноническое имя, версия ФОРМАТА (major, minor))` — свойство ФОРМЫ,\n\
         /// введённое версией. Витнесс — дельта дампов одной конфигурации, собранной разными\n\
         /// платформами (`models/version_facts.jsonl`, факт `since`).\n\
         pub static FORM_SINCE_RAW: &[(&str, &str, (u16, u16))] = &[\n",
    );
    for (owner, name, format) in &form_since {
        out.push_str(&format!(
            "    ({:?}, {:?}, {}),\n",
            owner,
            name,
            format_tuple(format)
        ));
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// `(владелец, каноническое имя, версия ИСТОЧНИКА, версия ЦЕЛИ, значение)` —\n\
         /// свойство контрола, которое ЦЕЛЬ проставляет САМА, поднимая источник (факт\n\
         /// `materialized`, `models/version_facts.jsonl`). Витнесс — поузловое сравнение\n\
         /// дампов одной конфигурации: тег получили ВСЕ узлы, у которых его не было, и\n\
         /// значение у всех одно.\n\
         #[allow(clippy::type_complexity)]\n pub static FORM_MATERIALIZED_RAW: &[(&str, &str, (u16, u16), (u16, u16), &str)] = &[\n",
    );
    for (owner, name, source, target, value) in &form_materialized {
        out.push_str(&format!(
            "    ({:?}, {:?}, {}, {}, {:?}),\n",
            owner,
            name,
            format_tuple(source),
            format_tuple(target),
            value
        ));
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// `(владелец, СТАРОЕ имя, НОВОЕ имя, версия ИСТОЧНИКА, версия ЦЕЛИ)` — свойство\n\
         /// контрола, ПЕРЕИМЕНОВАННОЕ версией (факт `renamed`): значение целиком переехало\n\
         /// из старого тега в новый (совпали файлы, число вхождений и сами значения).\n\
         #[allow(clippy::type_complexity)]\n pub static FORM_RENAMED_RAW: &[(&str, &str, &str, (u16, u16), (u16, u16))] = &[\n",
    );
    for (owner, from, to, source, target) in &form_renamed {
        out.push_str(&format!(
            "    ({:?}, {:?}, {:?}, {}, {}),\n",
            owner,
            from,
            to,
            format_tuple(source),
            format_tuple(target)
        ));
    }
    out.push_str("];\n");

    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR");
    std::fs::write(Path::new(&out_dir).join("since_tables.rs"), out).expect("write since tables");
}

/// Codegen ВЕРСИОННОГО РЕЕСТРА (`models/version_registry.jsonl`, FORMATS.md §7) —
/// сериализационная поверхность, проиндексированная версией формата.
///
/// # Почему codegen, а не чтение файла в рантайме
/// Ровно та же причина, что у since-таблиц: реестр — ДАННЫЕ репозитория, а не вход
/// программы. Читая его в рантайме, бинарь зависел бы от наличия рабочего дерева, а
/// рассинхрон «данные новее кода» вскрывался бы у пользователя, а не на сборке. Здесь
/// же битая запись — ОШИБКА СБОРКИ (§1.0), а не тихий пропуск.
///
/// Эмитим ЧЕТЫРЕ таблицы (все отсортированы — воспроизводимая сборка):
/// * `REGISTRY_VERSIONS` — версии формата, покрытые прогоном (ось реестра);
/// * `REGISTRY_KINDS` — вид объектов, СУЩЕСТВУЮЩИЙ в версии (роспись корня `.cf`);
/// * `REGISTRY_PROPERTIES` — свойство, наблюдённое в версии, + витнессированное умолчание;
/// * `REGISTRY_LITERALS` — литерал перечисления, наблюдённый в версии.
///
/// Версия здесь — уже версия ФОРМАТА (`2.20`): реестр собран из дампов, а дамп штампован
/// форматом. Перевода платформа→формат тут нет — он живёт в `VERSION_TABLE`.
fn emit_version_registry_tables() {
    /// Строка таблицы свойств: `(формат, владелец, элемент, каноническое имя,
    /// designer-имя, умолчание)`.
    type PropRow = (
        (u16, u16),
        String,
        String,
        String,
        String,
        Option<String>,
    );

    let path = repo_root().join("models/version_registry.jsonl");
    println!("cargo:rerun-if-changed={}", path.display());

    // (формат, вид)
    let mut kinds: Vec<((u16, u16), String)> = Vec::new();
    // (формат, class-guid группы корня, вид) — ИМЕНОВАННЫЕ группы росписи корня.
    let mut kind_guids: Vec<((u16, u16), String, String)> = Vec::new();
    // (формат, class-guid) — БЕЗЫМЯННЫЕ (зарезервированные платформой) группы корня.
    let mut unnamed_groups: Vec<((u16, u16), String)> = Vec::new();
    let mut props: Vec<PropRow> = Vec::new();
    // (формат, перечисление, литерал)
    let mut literals: Vec<((u16, u16), String, String)> = Vec::new();
    let mut versions: Vec<(u16, u16)> = Vec::new();

    for line in read_jsonl(&path) {
        let record = line["record"]
            .as_str()
            .expect("version_registry record has `record`");
        // Записи БЕЗ версионной оси (`enum` — состав литералов по метамодели, `rename` —
        // пара имён) в таблицы наличия не идут: наличие индексируется версией, а у них её нет.
        let Some(format) = line["format"].as_str() else {
            continue;
        };
        let fmt = format_pair(format);
        match record {
            "version" => {
                versions.push(fmt);
                // Группы корня, за которыми НЕ стоит именованный вид: платформа держит их
                // зарезервированными (count-0). Состав — тоже функция версии.
                for g in line["root_groups_unnamed"]
                    .as_array()
                    .map(Vec::as_slice)
                    .unwrap_or_default()
                {
                    unnamed_groups.push((
                        fmt,
                        g.as_str()
                            .expect("root_groups_unnamed carries guid strings")
                            .to_string(),
                    ));
                }
            }
            "kind" => {
                let kind = line["kind"]
                    .as_str()
                    .expect("kind record has `kind`")
                    .to_string();
                if let Some(guid) = line["class_guid"].as_str() {
                    kind_guids.push((fmt, guid.to_string(), kind.clone()));
                }
                kinds.push((fmt, kind));
            }
            "property" => {
                let owner = line["owner"].as_str().expect("property has `owner`");
                let element = line["element"].as_str().expect("property has `element`");
                let designer = line["designer"].as_str().expect("property has `designer`");
                // Ключ соединения со спеками — КАНОНИЧЕСКОЕ имя: имя EDT, если реестр его
                // разрешил, иначе Designer-имя, канонизированное той же конвенцией платформы
                // (различие — РОВНО регистр первой буквы; зеркало
                // `version::since::designer_name_to_canonical`).
                let canonical = match line["edt"].as_str() {
                    Some(edt) => edt.to_string(),
                    None => lower_first(designer),
                };
                props.push((
                    fmt,
                    owner.to_string(),
                    element.to_string(),
                    canonical,
                    designer.to_string(),
                    line["default"].as_str().map(str::to_string),
                ));
            }
            "enum_literal" => literals.push((
                fmt,
                line["enum"]
                    .as_str()
                    .expect("enum_literal has `enum`")
                    .to_string(),
                line["literal"]
                    .as_str()
                    .expect("enum_literal has `literal`")
                    .to_string(),
            )),
            // Незнакомый тип записи — ошибка ДАННЫХ, а не повод молча пропустить (§1.0).
            other => panic!("version_registry carries an unknown record type {other:?}"),
        }
    }

    versions.sort();
    versions.dedup();
    kinds.sort();
    kinds.dedup();
    kind_guids.sort();
    kind_guids.dedup();
    unnamed_groups.sort();
    unnamed_groups.dedup();
    props.sort();
    props.dedup();
    literals.sort();
    literals.dedup();
    assert!(
        !versions.is_empty() && !props.is_empty(),
        "models/version_registry.jsonl is empty — the registry codegen would silently \
         disable every registry-backed answer"
    );

    let mut out = String::from(
        "// @generated by build.rs from models/version_registry.jsonl — do not edit.\n\n",
    );
    out.push_str(
        "/// Версии формата, покрытые прогоном реестра (ось наличия). Отсутствие версии\n\
         /// в этом списке значит «реестр про неё не знает», а НЕ «в ней ничего нет».\n\
         pub static REGISTRY_VERSIONS: &[(u16, u16)] = &[\n",
    );
    for (major, minor) in &versions {
        out.push_str(&format!("    ({major}, {minor}),\n"));
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// `(версия формата, вид)` — вид объектов, СУЩЕСТВУЮЩИЙ в версии (роспись корня\n\
         /// `.cf`, собранного платформой: она несёт группу на каждый известный ей вид).\n\
         pub static REGISTRY_KINDS: &[((u16, u16), &str)] = &[\n",
    );
    for ((major, minor), kind) in &kinds {
        out.push_str(&format!("    (({major}, {minor}), {kind:?}),\n"));
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// `(версия формата, class-guid группы корня, вид)` — ИМЕНОВАННАЯ группа росписи\n\
         /// корня `.cf` этой версии. Ключ по guid'у нужен там, где вид известен только\n\
         /// платформенным guid'ом (состав B-блоков корня).\n\
         pub static REGISTRY_KIND_GUIDS: &[((u16, u16), &str, &str)] = &[\n",
    );
    for ((major, minor), guid, kind) in &kind_guids {
        out.push_str(&format!("    (({major}, {minor}), {guid:?}, {kind:?}),\n"));
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// `(версия формата, class-guid)` — БЕЗЫМЯННАЯ (зарезервированная платформой)\n\
         /// группа росписи корня: группа есть, именованного вида за ней нет. Состав —\n\
         /// функция версии ровно так же, как состав видов.\n\
         pub static REGISTRY_UNNAMED_ROOT_GROUPS: &[((u16, u16), &str)] = &[\n",
    );
    for ((major, minor), guid) in &unnamed_groups {
        out.push_str(&format!("    (({major}, {minor}), {guid:?}),\n"));
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// Свойство, НАБЛЮДЁННОЕ в версии, с витнессированным умолчанием этой версии.\n\
         pub static REGISTRY_PROPERTIES: &[RegistryProperty] = &[\n",
    );
    for (fmt, owner, element, canonical, designer, default) in &props {
        let default = match default {
            Some(d) => format!("Some({d:?})"),
            None => "None".to_string(),
        };
        out.push_str(&format!(
            "    RegistryProperty {{ format: ({}, {}), owner: {owner:?}, element: {element:?}, \
             canonical: {canonical:?}, designer: {designer:?}, default: {default} }},\n",
            fmt.0, fmt.1
        ));
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// `(версия формата, перечисление, литерал)` — литерал, НАБЛЮДЁННЫЙ в версии.\n\
         /// Наблюдение здесь — функция того, что использовала конфигурация прогона, поэтому\n\
         /// отсутствие литерала витнессом ОТСУТСТВИЯ НЕ является (см. `version::availability`).\n\
         pub static REGISTRY_LITERALS: &[((u16, u16), &str, &str)] = &[\n",
    );
    for ((major, minor), en, lit) in &literals {
        out.push_str(&format!("    (({major}, {minor}), {en:?}, {lit:?}),\n"));
    }
    out.push_str("];\n");

    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR");
    std::fs::write(
        Path::new(&out_dir).join("version_registry_tables.rs"),
        out,
    )
    .expect("write version registry tables");
}

/// Codegen РАСКЛАДОК сериализации (`models/format_layouts.jsonl`).
///
/// Раскладка — это форма КОНСТРУКЦИИ в конкретной версии формата: ведущее число записи,
/// число слотов, арность, ростер пространств имён. Снята с платформенных дампов
/// (`tools/build_format_layouts.py`), то есть НАБЛЮДЕНА, а не придумана. Рабочий код
/// спрашивает «какая форма у конструкции в версии V» вместо `if версия == …`.
///
/// Эмитим одну таблицу `FORMAT_LAYOUTS` (отсортированную — воспроизводимая сборка).
/// Битая запись — ОШИБКА СБОРКИ (§1.0), а не тихий пропуск.
fn emit_format_layout_tables() {
    let path = repo_root().join("models/format_layouts.jsonl");
    println!("cargo:rerun-if-changed={}", path.display());

    /// `(формат, конструкция, открыта ли вперёд, параметры, ростер ns, витнесс)`.
    type Row = (
        (u16, u16),
        String,
        bool,
        Vec<(String, String)>,
        Vec<(String, String)>,
        String,
    );
    let mut rows: Vec<Row> = Vec::new();

    for line in read_jsonl(&path) {
        let record = line["record"]
            .as_str()
            .expect("format_layouts record has `record`");
        if record != "layout" {
            panic!("format_layouts carries an unknown record type {record:?}");
        }
        let construct = line["construct"]
            .as_str()
            .expect("layout has `construct`")
            .to_string();
        let fmt = format_pair(line["format"].as_str().expect("layout has `format`"));
        let open_ended = match line["scope"].as_str().expect("layout has `scope`") {
            "from" => true,
            "exact" => false,
            other => panic!("format_layouts scope {other:?} is neither `exact` nor `from`"),
        };
        let mut params: Vec<(String, String)> = line["params"]
            .as_object()
            .map(|m| {
                m.iter()
                    .map(|(k, v)| {
                        (
                            k.clone(),
                            v.as_str()
                                .expect("layout params are strings")
                                .to_string(),
                        )
                    })
                    .collect()
            })
            .unwrap_or_default();
        params.sort();
        let ns: Vec<(String, String)> = line["ns"]
            .as_array()
            .map(|a| {
                a.iter()
                    .map(|pair| {
                        let p = pair.as_array().expect("ns entry is a pair");
                        (
                            p[0].as_str().expect("ns name").to_string(),
                            p[1].as_str().expect("ns uri").to_string(),
                        )
                    })
                    .collect()
            })
            .unwrap_or_default();
        let witness = line["witness"].as_str().unwrap_or("").to_string();
        rows.push((fmt, construct, open_ended, params, ns, witness));
    }

    rows.sort();
    rows.dedup();
    assert!(
        !rows.is_empty(),
        "models/format_layouts.jsonl is empty — every layout-backed answer would silently \
         turn into a refusal"
    );

    let mut out =
        String::from("// @generated by build.rs from models/format_layouts.jsonl — do not edit.\n\n");
    out.push_str("pub static FORMAT_LAYOUTS: &[Layout] = &[\n");
    for (fmt, construct, open_ended, params, ns, witness) in &rows {
        let params = params
            .iter()
            .map(|(k, v)| format!("({k:?}, {v:?})"))
            .collect::<Vec<_>>()
            .join(", ");
        let ns = ns
            .iter()
            .map(|(k, v)| format!("({k:?}, {v:?})"))
            .collect::<Vec<_>>()
            .join(", ");
        out.push_str(&format!(
            "    Layout {{ construct: {construct:?}, format: ({}, {}), open_ended: {open_ended}, \
             params: &[{params}], ns: &[{ns}], witness: {witness:?} }},\n",
            fmt.0, fmt.1
        ));
    }
    out.push_str("];\n");

    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR");
    std::fs::write(Path::new(&out_dir).join("format_layout_tables.rs"), out)
        .expect("write format layout tables");
}

/// Корень репозитория (крейт лежит в `crates/core`).
fn repo_root() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .expect("repo root from crates/core")
        .to_path_buf()
}

/// Первая буква — в нижний регистр (`LineNumberLength` → `lineNumberLength`). Конвенция
/// ПЛАТФОРМЫ: Designer-имя и EDT-имя различаются РОВНО регистром первой буквы.
fn lower_first(s: &str) -> String {
    let mut chars = s.chars();
    match chars.next() {
        Some(first) => first.to_lowercase().chain(chars).collect(),
        None => String::new(),
    }
}

/// `"2.21"` → `(2, 21)` как ЗНАЧЕНИЕ (в отличие от [`format_tuple`], который печатает код).
fn format_pair(s: &str) -> (u16, u16) {
    let parts: Vec<u16> = s
        .split('.')
        .map(|p| {
            p.parse()
                .unwrap_or_else(|_| panic!("version_registry carries a malformed format {s:?}"))
        })
        .collect();
    match parts.as_slice() {
        [major, minor] => (*major, *minor),
        _ => panic!("version_registry format {s:?} is not `major.minor`"),
    }
}

/// `"2.21"` → `(2, 21)`. Не разбираемая версия — ОШИБКА сборки (§1.0), а не тихий пропуск.
fn format_tuple(s: &str) -> String {
    let parts: Vec<u16> = s
        .split('.')
        .map(|p| {
            p.parse()
                .unwrap_or_else(|_| panic!("version_facts carries a malformed format {s:?}"))
        })
        .collect();
    match parts.as_slice() {
        [major, minor] => format!("({major}, {minor})"),
        _ => panic!("version_facts format {s:?} is not `major.minor`"),
    }
}

/// `"8.3.27"` → `(8, 3, 27)`. Версия, не разбираемая как три числа, — ОШИБКА сборки
/// (§1.0: не «пропустить молча» — инвентарь обязан быть корректен).
fn platform_tuple(s: &str) -> String {
    let parts: Vec<u16> = s
        .split('.')
        .map(|p| {
            p.parse::<u16>()
                .unwrap_or_else(|_| panic!("malformed `since` version in inventory: {s:?}"))
        })
        .collect();
    match parts[..] {
        [a, b, c] => format!("({a}, {b}, {c})"),
        _ => panic!("`since` must be major.minor.patch, got {s:?}"),
    }
}

/// Прочитать JSONL (по объекту на строку). Пустые строки пропускаются.
fn read_jsonl(path: &Path) -> Vec<serde_json::Value> {
    let text = std::fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    text.lines()
        .filter(|l| !l.trim().is_empty())
        .map(|l| {
            serde_json::from_str(l)
                .unwrap_or_else(|e| panic!("parse {}: {e}", path.display()))
        })
        .collect()
}
